    static const rmr_fc16_u8 name[13]={'c','u','s','t','o','d','y','1','6','.','b','i','n'};if(!payload||!out||!out_len||n>0xffffffffu)return RMR_FC16_ERR_ARGUMENT;rmr_fc16_usize need=30u+13u+n+46u+13u+22u;if(cap<need)return RMR_FC16_ERR_CAPACITY;rmr_fc16_u32 crc=rmr_fc16_crc32_ieee(payload,n);rmr_fc16_usize o=0u;p32(out+o,0x04034b50u);o+=4u;p16(out+o,20u);o+=2u;p16(out+o,0u);o+=2u;p16(out+o,0u);o+=2u;p16(out+o,0u);o+=2u;p16(out+o,0u);o+=2u;p32(out+o,crc);o+=4u;p32(out+o,(rmr_fc16_u32)n);o+=4u;p32(out+o,(rmr_fc16_u32)n);o+=4u;p16(out+o,13u);o+=2u;p16(out+o,0u);o+=2u;copyb(out+o,name,13u);o+=13u;copyb(out+o,payload,n);o+=n;rmr_fc16_usize cd=o;p32(out+o,0x02014b50u);o+=4u;p16(out+o,20u);o+=2u;p16(out+o,20u);o+=2u;p16(out+o,0u);o+=2u;p16(out+o,0u);o+=2u;p16(out+o,0u);o+=2u;p16(out+o,0u);o+=2u;p32(out+o,crc);o+=4u;p32(out+o,(rmr_fc16_u32)n);o+=4u;p32(out+o,(rmr_fc16_u32)n);o+=4u;p16(out+o,13u);o+=2u;p16(out+o,0u);o+=2u;p16(out+o,0u);o+=2u;p16(out+o,0u);o+=2u;p16(out+o,0u);o+=2u;p32(out+o,0u);o+=4u;p32(out+o,0u);o+=4u;copyb(out+o,name,13u);o+=13u;rmr_fc16_usize cds=o-cd;p32(out+o,0x06054b50u);o+=4u;p16(out+o,0u);o+=2u;p16(out+o,0u);o+=2u;p16(out+o,1u);o+=2u;p16(out+o,1u);o+=2u;p32(out+o,(rmr_fc16_u32)cds);o+=4u;p32(out+o,(rmr_fc16_u32)cd);o+=4u;p16(out+o,0u);o+=2u;*out_len=o;return RMR_FC16_OK;
