rmr_fc16_u32 rmr_fc16_zip_verify_roundtrip(const rmr_fc16_u8 *z,rmr_fc16_usize zn,const rmr_fc16_u8 *e,rmr_fc16_usize en){if(!z||!e||zn<43u||g32(z)!=0x04034b50u)return RMR_FC16_ERR_ARGUMENT;if(g16(z+8u)!=0u)return RMR_FC16_ERR_INTEGRITY;rmr_fc16_u32 crc=g32(z+14u),cs=g32(z+18u),us=g32(z+22u);rmr_fc16_u16 nl=g16(z+26u),xl=g16(z+28u);if(cs!=us||us!=en)return RMR_FC16_ERR_INTEGRITY;rmr_fc16_usize off=30u+nl+xl;if(off+en>zn)return RMR_FC16_ERR_INTEGRITY;rmr_fc16_u8 d=0u;for(rmr_fc16_usize i=0u;i<en;++i)d|=z[off+i]^e[i];if(d||rmr_fc16_crc32_ieee(z+off,en)!=crc)return RMR_FC16_ERR_INTEGRITY;return RMR_FC16_OK;}
